    cal_rc_why_1: 'A generic calculator used your total weight, not your lean mass — that alone can be off by a few hundred kcal.',
    cal_rc_why_2: 'Activity level is the most over-selected input. If in doubt, pick one level lower.',
    cal_rc_why_3: 'As you lose weight, a smaller body burns less — your old target is now closer to maintenance.',
