    cal_expl_scale_title: 'Why the scale lies (water & glycogen)',
    cal_expl_scale_body: 'Your weight on the scale isn\'t just fat. Glycogen — the carbohydrate your muscles store for energy — binds about 3 g of water for every gram of glycogen, and your body holds roughly 400–500 g of it. So just going from low glycogen (empty muscles) to full can swing the scale 1.5–2 kg (3–4 lb) with no change in fat at all. Add sodium, a big meal, your menstrual cycle, stress, and normal digestion, and 1–3 kg (2–7 lb) of day-to-day bounce is completely normal. Someone in a genuine fat-loss deficit can still watch the scale climb for a week. You can\'t calculate this noise away — weigh yourself under the same conditions (morning, after the bathroom, before eating) and judge the trend over weeks, not days.',
    cal_expl_deficit_title: 'Why "500 kcal = 1 lb/week" stops working',
    cal_expl_deficit_body: 'The "500 kcal a day = 1 lb a week" rule comes from the idea that a pound of fat holds about 3,500 kcal. It\'s a fine short-term ballpark, but it assumes your metabolism never changes. As you lose weight, a smaller body burns fewer calories, so your maintenance number falls with it — real loss is a curve that flattens, not a straight line. Expecting a straight line and hitting the inevitable plateau is one of the biggest reasons people conclude something is broken. Recalculate every few kilos and lower the target as your body changes.',
    cal_expl_measure_title: 'Why measurements beat the scale',
    cal_expl_measure_body: 'A tape measure around your waist is cheap, and it tracks fat loss far more clearly than the scale — which is muddied by water, food and glycogen. If you\'re eating well below maintenance you may lose a little lean mass alongside fat, so the scale stalls and you assume it\'s failing. But if your waist is down while your weight is flat, that\'s recomposition — real progress you\'d never see on the scale alone. Measure at the same spot, first thing in the morning, every few weeks.',
