    settings_signout: 'Cerrar sesión',
    settings_signout_confirm: '¿Estás seguro de que deseas cerrar sesión?',
    settings_delete: 'Eliminar cuenta',
    settings_delete_msg: 'Para eliminar tu cuenta y todos los datos, envía un correo a hello@dosetrace.io. Esto no se puede deshacer.',
    settings_delete_permanent_msg: 'Esto eliminará permanentemente tu cuenta. Todos tus datos se perderán y esto no se puede deshacer.',
