    cal_rc_why_1: 'Una calculadora genérica usó tu peso total, no tu masa magra; solo eso puede desviar unos cientos de kcal.',
    cal_rc_why_2: 'El nivel de actividad es el dato que más se sobreestima. En la duda, elige uno más bajo.',
