    export_no_vaccines: 'Sin vacunas registradas.',
    export_exported_prefix: 'Exportado el',
    cal_expl_scale_title: 'Por qué la báscula engaña (agua y glucógeno)',
    cal_expl_scale_body: 'El peso en la báscula no es solo grasa. El glucógeno —el carbohidrato que tus músculos almacenan como energía— retiene unos 3 g de agua por cada gramo de glucógeno, y tu cuerpo guarda alrededor de 400–500 g. Solo con pasar de poco glucógeno (músculos vacíos) a músculos llenos, la báscula puede variar 1,5–2 kg sin que nada de eso sea grasa. Suma el sodio, una comida abundante, el ciclo menstrual, el estrés y la digestión normal, y 1–3 kg de oscilación diaria es totalmente normal. Alguien en un déficit real de grasa puede ver subir la báscula durante una semana. No hay forma de calcular esa variación: pésate siempre en las mismas condiciones (por la mañana, después del baño, antes de comer) y juzga la tendencia por semanas, no por días.',
    cal_expl_deficit_title: 'Por qué "500 kcal = 0,5 kg/semana" deja de funcionar',
    cal_expl_deficit_body: 'La regla de "500 kcal al día = 0,5 kg por semana" viene de que medio kilo de grasa contiene unas 3.500 kcal. Es una buena aproximación a corto plazo, pero supone que tu metabolismo nunca cambia. A medida que pierdes peso, un cuerpo más pequeño quema menos calorías, así que tu mantenimiento baja con él: la pérdida real es una curva que se aplana, no una línea recta. Esperar una línea recta y toparse con el inevitable estancamiento es una de las mayores razones por las que la gente cree que algo está roto. Recalcula cada pocos kilos y baja el objetivo a medida que tu cuerpo cambia.',
    cal_expl_measure_title: 'Por qué las medidas superan a la báscula',
    cal_expl_measure_body: 'Una cinta métrica alrededor de la cintura es barata y refleja la pérdida de grasa mucho más claramente que la báscula, enturbiada por el agua, la comida y el glucógeno. Si comes muy por debajo de tu mantenimiento, puedes perder algo de masa magra junto con la grasa, así que la báscula se estanca y crees que falla. Pero si tu cintura baja mientras el peso no se mueve, eso es recomposición: progreso real que nunca verías solo con la báscula. Mídete en el mismo punto, a primera hora de la mañana, cada pocas semanas.',
    vax_disclaimer: 'Tú ingresas tus propios registros de vacunas. DoseTrace los guarda y organiza — nunca aconseja qué vacunas ponerte ni cuándo. Para cualquier duda médica, consulta a un profesional cualificado.',
    vax_add: 'Añadir vacuna',
    vax_scan: 'Escanear / subir',
