    export_exported_prefix: 'Exportado em',
    cal_expl_scale_title: 'Por que a balança engana (água e glicogênio)',
    cal_expl_scale_body: 'O peso na balança não é só gordura. O glicogênio — o carboidrato que seus músculos armazenam como energia — retém cerca de 3 g de água para cada grama de glicogênio, e seu corpo guarda por volta de 400–500 g dele. Só de sair de pouco glicogênio (músculos vazios) para o músculo cheio, a balança já pode variar 1,5–2 kg sem que nada disso seja gordura. Some o sódio, uma refeição grande, o ciclo menstrual, o estresse e a digestão normal, e 1–3 kg de oscilação diária é perfeitamente normal. Quem está num déficit real de gordura pode ver a balança subir por uma semana inteira. Não dá para calcular essa variação: pese-se sempre nas mesmas condições (de manhã, após o banheiro, antes de comer) e avalie a tendência por semanas, não por dias.',
    cal_expl_deficit_title: 'Por que "500 kcal = 0,5 kg/semana" deixa de funcionar',
    cal_expl_deficit_body: 'A regra de "500 kcal por dia = 0,5 kg por semana" vem da ideia de que meio quilo de gordura contém cerca de 3.500 kcal. É uma boa aproximação de curto prazo, mas pressupõe que seu metabolismo nunca muda. À medida que você perde peso, um corpo menor queima menos calorias, então sua manutenção cai junto — a perda real é uma curva que achata, não uma linha reta. Esperar uma linha reta e bater no inevitável platô é uma das maiores razões pelas quais as pessoas acham que algo está errado. Recalcule a cada poucos quilos e reduza a meta conforme seu corpo muda.',
    cal_expl_measure_title: 'Por que as medidas superam a balança',
    cal_expl_measure_body: 'Uma fita métrica na cintura é barata e acompanha a perda de gordura muito mais claramente do que a balança, que é turvada por água, comida e glicogênio. Se você come bem abaixo da manutenção, pode perder um pouco de massa magra junto com a gordura, então a balança estagna e você acha que está falhando. Mas se sua cintura diminui enquanto o peso não se move, isso é recomposição: progresso real que você nunca veria só com a balança. Meça no mesmo ponto, logo de manhã, a cada poucas semanas.',
    vax_disclaimer: 'Você insere seus próprios registros de vacinas. O DoseTrace os guarda e organiza — nunca aconselha quais vacinas tomar ou quando. Para qualquer dúvida médica, consulte um profissional qualificado.',
