    faq_categories: [
      {
        category: 'ERSTE SCHRITTE',
        questions: [
          {
            q: 'Was ist DoseTrace?',
            a: 'DoseTrace ist eine Wellness-Tracking-App zur Verwaltung von Substanzen, Dosen und Fläschchen. Sie enthält einen Rekonstitutions-Rechner, Spritzenführer und Injektionsprotokoll.'
          },
          {
            q: 'Ist DoseTrace kostenlos?',
            a: 'Ja! Die Kernfunktionen sind für immer kostenlos. Premium entsperrt Cloud-Synchronisierung, unbegrenzte Protokolle, Blutuntersuchungs-KI und mehr.'
          },
          {
            q: 'Wie füge ich mein erstes Protokoll hinzu?',
            a: 'Geh zum Tab Protokolle, tippe auf "+ Hinzufügen", wähle deinen Substanztyp und folge den Schritten, um deine Dosisdetails einzurichten.'
          }
        ]
      },
      {
        category: 'REKONSTITUTION & DOSIERUNG',
        questions: [
          {
            q: 'Wie funktioniert der Rekonstitutions-Rechner?',
            a: 'Gib deine Substanzmenge und das Volumen des hinzugefügten bakteriostatischen Wassers ein. DoseTrace berechnet die Konzentration und zeigt genau, wie viel du in deiner Spritze aufziehen musst.'
          },
          {
            q: 'Welche Spritzengrößen werden unterstützt?',
            a: 'DoseTrace unterstützt 1 ml (100 Einheiten), 0,5 ml (50 Einheiten) und 0,3 ml (30 Einheiten) Insulinspritzen.'
          },
          {
            q: 'Wie lange hält eine rekonstituiertes Fläschchen?',
            a: 'Die meisten rekonstituierten Peptide bleiben etwa 30 Tage lang stabil, wenn sie im Kühlschrank mit bakteriostatischem Wasser gelagert werden.'
          }
        ]
      },
      {
        category: 'FLÄSCHCHEN & VERFOLGUNG',
        questions: [
          {
            q: 'Wie protokolliere ich ein Fläschchen-Mischen?',
            a: 'Wenn du ein neues gefriergetrocknetes Protokoll erstellst, kannst du das Mischdatum sofort protokollieren. Du kannst Fläschchen auch jederzeit im Fläschchen-Tab hinzufügen.'
          },
          {
            q: 'Was passiert, wenn ein Fläschchen abläuft?',
            a: 'DoseTrace zeigt eine Warnung an, wenn sich dein Fläschchen seinem 30-Tage-Ablaufdatum nähert. Abgelaufene Fläschchen werden rot markiert.'
          }
        ]
      },
      {
        category: 'BLUTUNTERSUCHUNG',
        questions: [
          {
            q: 'Wie funktioniert der Blutuntersuchungs-Upload?',
            a: 'Lade einen PDF-Laborbericht hoch und unsere KI extrahiert automatisch alle Biomarker-Werte. Es funktioniert mit LabCorp, Quest und den meisten Berichten privater Kliniken.'
          },
          {
            q: 'Sind meine Blutuntersuchungsdaten privat?',
            a: 'Ja. Kostenlose Konten speichern alles lokal auf deinem Gerät. Premium-Konten verwenden verschlüsselte Cloud-Speicher.'
          }
        ]
      },
      {
        category: 'PREMIUM',
        questions: [
          {
            q: 'Was ist in Premium enthalten?',
            a: 'Cloud-Sicherung, Synchronisierung auf mehreren Geräten, unbegrenzte Protokolle, unbegrenzte Blutuntersuchungs-Uploads, Realitätscheck und Fortschritt, PDF-Export und bevorzugter Support.'
          },
          {
            q: 'Wie viel kostet Premium?',
            a: 'Die aktuellen Preise für Premium (monatlich und jährlich) werden in der App auf dem Upgrade-Bildschirm angezeigt. Beide Pläne beinhalten eine kostenlose 7-Tage-Testversion.'
          },
          {
            q: 'Kann ich jederzeit kündigen?',
            a: 'Ja. Kündige mindestens 24 Stunden vor deinem Verlängerungsdatum in Einstellungen → Apple ID → Abonnements.'
          }
        ]
      }
    ],

