    blood_title: 'Blutuntersuchung',
    body_section_labs: 'Labor',
    body_section_vaccines: 'Impfungen',
    body_section_calc: 'Rechner',
    body_hub_subtitle: 'Deine Daten & Körperwerte',
    body_hub_welcome: 'Dein Raum für alles rund um deinen Körper — an einem ruhigen Ort und immer deins.',
    body_hub_intro: 'Alles hier gibst du selbst ein oder lädst es hoch. DoseTrace ordnet es — es interpretiert oder berät nie.',
    body_card_labs_title: 'Laborwerte-Tagebuch',
    body_card_labs_desc: 'Bewahre jeden Bluttest an einem Ort auf. Stelle jeden Marker über die Zeit dar, beschrifte deine Tests und exportiere einen sauberen Verlauf für jeden Arzt.',
