    cal_rc_result_prefix: 'Dein echter Erhaltungsbedarf liegt bei etwa',
    cal_rc_locked_intro: 'Generische Rechner schätzen deinen Tagesverbrauch mit Formeln. Dieser findet deine ECHTE Zahl aus dem, was wirklich mit deinem Körper passiert ist — das Rätsel, das die meisten Rechner nicht lösen.',
    cal_rc_locked_lead: 'Es braucht nur vier Zahlen, die du schon hast:',
    cal_rc_locked_payoff: 'Du siehst genau, wie viele Kalorien dein Körper wirklich verbrennt — und wie schnell du tatsächlich ab- oder zunimmst, Woche für Woche.',
