    cal_rc_vs: 'Eine generische Schätzung ergab',
    cal_rc_why_title: 'DAS IST WAHRSCHEINLICH LOS',
    cal_rc_why_1: 'Ein generischer Rechner nutzte dein Gesamtgewicht, nicht deine Magermasse — das allein kann um einige hundert kcal danebenliegen.',
    cal_rc_why_2: 'Das Aktivitätsniveau wird am häufigsten zu hoch gewählt. Im Zweifel eine Stufe niedriger.',
    cal_rc_why_3: 'Wenn du abnimmst, verbraucht ein kleinerer Körper weniger — dein altes Ziel liegt jetzt näher am Erhalt.',
    cal_rc_why_4: 'Die Zufuhr ist meist höher als erinnert. Das ist der häufigste Grund überhaupt.',
    cal_rc_why_5: 'Wasser und Glykogen können echten Fettabbau wochenlang verdecken — siehe die Erklärungen unten.',
    cal_rc_unreliable_note: 'Selbst angegebene Zufuhr liegt oft 20-40 % daneben, und dieser Fehler steckt in dieser Zahl. Wirkt sie unplausibel niedrig, ist das selbst ein Hinweis, dass du mehr isst als gedacht.',
    cal_rc_too_short: 'Dieser Zeitraum ist zu kurz. Nimm Wägungen mit mindestens 14 Tagen Abstand für eine belastbare Zahl.',
    cal_rc_maintenance: 'Dein Gewicht hat sich kaum verändert — das ist im Grunde Erhalt, zu klein, um einen verlässlichen Verbrauch zu berechnen.',
    cal_rc_implausible: 'Das Ergebnis ist unplausibel niedrig, was fast immer heißt, dass die Tageszufuhr höher war als erinnert (20-40 % Unterschätzung sind gut belegt). Vertraue der Schätzung oben und erfasse die Zufuhr genauer.',
    cal_snap_title: 'Fortschritt',
    cal_snap_sub: 'Premium. Speichere bei jeder Nutzung eine Momentaufnahme und beobachte Gewicht und Taille zusammen. Wenn die Taille sinkt, während das Gewicht stagniert, ist das der Fettabbau, den die Waage verbirgt.',
