    curve_tier_clinical: 'Dati clinici',
    curve_tier_studied: 'Studi sull’uomo',
    curve_tier_estimated: 'Stimato — nessun dato umano',
    curve_disclaimer: '⚠️ Modello stimato basato su emivite di eliminazione pubblicate e sulle dosi registrate. La farmacocinetica individuale varia notevolmente. Questa è una visualizzazione educativa — non una misurazione dei livelli ematici reali. Conferma con vere analisi del sangue.',
    curve_compounds_label: 'composti',
    curve_choose_title: 'Scegli i composti',
    curve_choose_hint: 'Seleziona uno o più per sovrapporre le curve.',
    curve_done: 'Fine',
    faq_categories: [
      {
        category: 'INIZIARE',
        questions: [
          {
            q: 'Che cos\'è DoseTrace?',
            a: 'DoseTrace è un\'app di tracciamento del benessere personale per gestire composti, dosi e flaconi. Include un calcolatore di ricostituizione, una guida alla siringa e un registro di iniezioni.'
          },
          {
            q: 'DoseTrace è gratuito?',
            a: 'Sì! Le funzioni principali sono gratuite per sempre. Premium sblocca la sincronizzazione cloud, protocolli illimitati, IA per analisi e altro ancora.'
          },
          {
            q: 'Come aggiungo il mio primo protocollo?',
            a: 'Vai alla scheda Protocolli, tocca "+ Aggiungi", scegli il tipo di composto e segui i passaggi per configurare i dettagli della tua dose.'
          }
        ]
      },
      {
        category: 'RICOSTITUIZIONE E DOSAGGIO',
        questions: [
          {
            q: 'Come funziona il calcolatore di ricostituizione?',
            a: 'Inserisci la tua quantità di composto e il volume di acqua batteriostatica che hai aggiunto. DoseTrace calcola la concentrazione e ti mostra esattamente quanto prelevare nella tua siringa.'
          },
          {
            q: 'Quali taglie di siringhe sono supportate?',
            a: 'DoseTrace supporta siringhe da insulina da 1 ml (100 unità), 0,5 ml (50 unità) e 0,3 ml (30 unità).'
          },
          {
            q: 'Quanto dura un flacone ricostituito?',
            a: 'La maggior parte dei peptidi ricostituti rimane stabile per circa 30 giorni se conservati in frigorifero con acqua batteriostatica.'
          }
        ]
      },
      {
        category: 'FLACONI E TRACCIAMENTO',
        questions: [
          {
            q: 'Come registro una miscelazione di flacone?',
            a: 'Quando crei un nuovo protocollo liofilizzato, puoi registrare la data di miscelazione subito. Puoi anche aggiungere flaconi in qualsiasi momento dalla scheda Flaconi.'
          },
          {
            q: 'Che cosa succede quando un flacone scade?',
            a: 'DoseTrace mostrerà un avviso quando il tuo flacone si avvicina alla scadenza di 30 giorni. I flaconi scaduti sono segnati in rosso.'
          }
        ]
      },
      {
        category: 'ANALISI',
        questions: [
          {
            q: 'Come funziona il caricamento delle analisi?',
            a: 'Carica un rapporto di laboratorio in PDF e la nostra IA estrae automaticamente tutti i valori dei biomarker. Funziona con LabCorp, Quest e la maggior parte dei rapporti delle cliniche private.'
          },
          {
            q: 'I miei dati delle analisi sono privati?',
            a: 'Sì. Gli account gratuiti memorizzano tutto localmente sul tuo dispositivo. Gli account Premium utilizzano l\'archiviazione cloud crittografata.'
          }
        ]
      },
      {
        category: 'PREMIUM',
        questions: [
          {
            q: 'Cosa è incluso in Premium?',
            a: 'Backup cloud, sincronizzazione multi-dispositivo, protocolli illimitati, caricamenti di analisi illimitati, verifica reale e progressi, esportazione PDF e supporto prioritario.'
          },
          {
            q: 'Quanto costa Premium?',
            a: 'I prezzi attuali di Premium mensile e annuale sono mostrati nell\'app nella schermata di upgrade. Entrambi i piani includono una prova gratuita di 7 giorni.'
          },
          {
            q: 'Posso annullare in qualsiasi momento?',
            a: 'Sì. Annulla almeno 24 ore prima della data di rinnovo in Impostazioni → Apple ID → Abbonamenti.'
          }
        ]
      }
    ],

