    cal_rc_why_title: 'ECCO COSA STA PROBABILMENTE ACCADENDO',
    cal_rc_why_1: 'Un calcolatore generico ha usato il tuo peso totale, non la massa magra — solo questo può sbagliare di qualche centinaio di kcal.',
    cal_rc_why_2: 'Il livello di attività è il dato più sovrastimato. Nel dubbio, scegline uno più basso.',
    cal_rc_why_3: 'Man mano che perdi peso, un corpo più piccolo brucia meno: il tuo vecchio obiettivo ora è vicino al mantenimento.',
    cal_rc_why_4: 'L\'apporto è spesso più alto di quanto ricordato. È la causa più comune in assoluto.',
    cal_rc_why_5: 'Acqua e glicogeno possono mascherare la perdita di grasso per settimane — vedi le spiegazioni sotto.',
    cal_rc_unreliable_note: 'L\'apporto autodichiarato sbaglia spesso del 20-40%, e quell\'errore entra in questo numero. Se sembra troppo basso, è già un indizio che mangi più di quanto pensi.',
    cal_rc_too_short: 'Quell\'intervallo è troppo breve. Usa pesate ad almeno 14 giorni di distanza per un numero attendibile.',
