    export_exported_prefix: 'Esportato il',
    cal_expl_scale_title: 'Perché la bilancia inganna (acqua e glicogeno)',
    cal_expl_scale_body: 'Il peso sulla bilancia non è solo grasso. Il glicogeno — il carboidrato che i tuoi muscoli immagazzinano come energia — trattiene circa 3 g di acqua per grammo di glicogeno, e il tuo corpo ne conserva all\'incirca 400–500 g. Solo passando da poco glicogeno (muscoli scarichi) a muscoli pieni, la bilancia può oscillare di 1,5–2 kg senza che nulla di ciò sia grasso. Aggiungi il sodio, un pasto abbondante, il ciclo mestruale, lo stress e la normale digestione, e 1–3 kg di oscillazione quotidiana è del tutto normale. Chi è in un reale deficit di grasso può vedere la bilancia salire per una settimana. Non c\'è modo di calcolare queste variazioni: pesati sempre nelle stesse condizioni (al mattino, dopo il bagno, prima di mangiare) e valuta la tendenza per settimane, non per giorni.',
    cal_expl_deficit_title: 'Perché "500 kcal = 0,5 kg/settimana" smette di funzionare',
    cal_expl_deficit_body: 'La regola "500 kcal al giorno = 0,5 kg a settimana" nasce dall\'idea che mezzo chilo di grasso contenga circa 3.500 kcal. È una buona approssimazione a breve termine, ma presuppone che il tuo metabolismo non cambi mai. Man mano che perdi peso, un corpo più piccolo brucia meno calorie, quindi il tuo mantenimento scende con esso: la perdita reale è una curva che si appiattisce, non una linea retta. Aspettarsi una linea retta e sbattere contro l\'inevitabile stallo è uno dei motivi principali per cui si pensa che qualcosa non funzioni. Ricalcola ogni pochi chili e abbassa l\'obiettivo man mano che il corpo cambia.',
    cal_expl_measure_title: 'Perché le misure battono la bilancia',
    cal_expl_measure_body: 'Un metro da sarto intorno alla vita costa poco e segue la perdita di grasso molto più chiaramente della bilancia, offuscata da acqua, cibo e glicogeno. Se mangi ben sotto il mantenimento puoi perdere un po\' di massa magra insieme al grasso, quindi la bilancia si blocca e pensi che non funzioni. Ma se la vita cala mentre il peso resta fermo, è ricomposizione: un progresso reale che con la sola bilancia non vedresti mai. Misura nello stesso punto, appena sveglio al mattino, ogni poche settimane.',
